**14. Crear componente Dashboard:**
```typescript
// frontend/src/components/Dashboard.tsx
import React, { useState, useEffect } from 'react';
import axios from 'axios';

interface Post {
    _id: string;
    title: string;
    content: string;
    category: string;
    author: { username: string };
    createdAt: string;
}

const Dashboard: React.FC = () => {
    const [posts, setPosts] = useState<Post[]>([]);
    const [loading, setLoading] = useState(true);
    const [newPost, setNewPost] = useState({ title: '', content: '', category: 'otros' });

    useEffect(() => {
        fetchPosts();
    }, []);

    const fetchPosts = async () => {
        try {
            const token = localStorage.getItem('token');
            const response = await axios.get('/api/posts', {
                headers: { Authorization: `Bearer ${token}` }
            });
            setPosts(response.data.data);
        } catch (error) {
            console.error('Error fetching posts:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreatePost = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            const token = localStorage.getItem('token');
            await axios.post('/api/posts', newPost, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setNewPost({ title: '', content: '', category: 'otros' });
            fetchPosts();
        } catch (error) {
            console.error('Error creating post:', error);
        }
    };

    if (loading) return <div>Cargando...</div>;

    return (
        <div className="container mx-auto p-4">
            <h1 className="text-3xl font-bold mb-8">Dashboard</h1>

            {/* Formulario para crear posts */}
            <form onSubmit={handleCreatePost} className="mb-8 bg-white p-6 rounded shadow">
                <h2 className="text-xl font-bold mb-4">Crear Nuevo Post</h2>
                <div className="mb-4">
                    <input
                        type="text"
                        placeholder="Título"
                        value={newPost.title}
                        onChange={(e) => setNewPost({...newPost, title: e.target.value})}
                        className="w-full p-2 border rounded mb-2"
                        required
                    />
                </div>
                <div className="mb-4">
                    <textarea
                        placeholder="Contenido"
                        value={newPost.content}
                        onChange={(e) => setNewPost({...newPost, content: e.target.value})}
                        className="w-full p-2 border rounded mb-2"
                        rows={4}
                        required
                    />
                </div>
                <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded">
                    Publicar Post
                </button>
            </form>

            {/* Lista de posts */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {posts.map(post => (
                    <div key={post._id} className="bg-white rounded shadow p-4">
                        <h3 className="font-bold text-lg mb-2">{post.title}</h3>
                        <p className="text-gray-600 mb-2">{post.content.substring(0, 100)}...</p>
                        <div className="text-sm text-gray-500">
                            <span>Por: {post.author.username}</span>
                            <span className="ml-4">Categoría: {post.category}</span>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Dashboard;
```

