**75. Crear sistema de backup automático:**
```javascript
// backend/scripts/backup.js
import mongoose from 'mongoose';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const backupDatabase = async () => {
    try {
        const collections = await mongoose.connection.db.listCollections().toArray();
        const backupData = {};
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

        for (const collection of collections) {
            const data = await mongoose.connection.db
                .collection(collection.name)
                .find({})
                .toArray();
            backupData[collection.name] = data;
        }

        const backupPath = path.join(__dirname, '../backups', `backup-${timestamp}.json`);
        fs.writeFileSync(backupPath, JSON.stringify(backupData, null, 2));

        console.log(`✅ Backup creado: ${backupPath}`);

        // Limpiar backups antiguos (mantener solo últimos 7 días)
        const backupsDir = path.join(__dirname, '../backups');
        const files = fs.readdirSync(backupsDir);
        const weekAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);

        files.forEach(file => {
            const filePath = path.join(backupsDir, file);
            const stats = fs.statSync(filePath);
            if (stats.mtimeMs < weekAgo) {
                fs.unlinkSync(filePath);
                console.log(`🗑️ Backup eliminado: ${file}`);
            }
        });

    } catch (error) {
        console.error('❌ Error en backup:', error);
    }
};

// Ejecutar backup cada día a las 2 AM
setInterval(backupDatabase, 24 * 60 * 60 * 1000);

// Ejecutar inmediatamente al iniciar
backupDatabase();
```

